#pragma once
#include <cstdint>
namespace ataxx {
struct PatternWeights {
std::int16_t table[6][19683], square[6][49], linear[6][4], tempo[6], line[6][4][1134], edge[6][3][6561];
};
inline const PatternWeights& patternWeights() {
    static const PatternWeights weights = [] {
        const char* data = "";
        const char* alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        int digits[128]{};
        for (int i = 0; i < 64; ++i) digits[int(alphabet[i])] = i;
        PatternWeights result;
        auto* out = reinterpret_cast<unsigned char*>(&result);
        for (unsigned i = 0; i < sizeof(result) / 3; ++i) {
            unsigned value = (digits[int(data[4*i])] << 18) | (digits[int(data[4*i+1])] << 12) | (digits[int(data[4*i+2])] << 6) | digits[int(data[4*i+3])];
            out[3*i] = value >> 16;
            out[3*i+1] = value >> 8;
            out[3*i+2] = value;
        }
        return result;
    }();
    return weights;
}
}
